    padding: 1rem;
}

.product-name {
    margin: 0 0 0.5rem;
    font-size: 1rem;
}

.product-price {
    font-weight: bold;
    color: #198754;
    margin: 0 0 0.5rem;
}

.product-rating {
    color: #ffc107;
    margin-bottom: 0.5rem;
}

.badge-out-of-stock {
    display: inline-block;
    background-color: #dc3545;
    color: white;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    background-color: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-to-cart:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-add-to-cart:disabled {
    background-color: #ccc;
    cursor: not-allowed;
}

